 <div className="lower-grid"><section className="panel"><div className="section-title compact"><h2>Next unlock</h2><button className="text-button" onClick={()=>setTab('rewards')}>View rewards</button></div>{nextReward?<div className="next-unlock"><div className="reward-emblem"><Lock size={28}/></div><div><p className="eyebrow">{subject.name} · {nextReward.hours} hours</p><h3>{nextReward.name}</h3><p className="muted">{formatTime(Math.max(0,nextReward.hours*3600000-data.totals[selected]))} of study to unlock.</p></div></div>:<div className="next-unlock"><Trophy/><p>You’ve earned every {subject.name} reward. Keep exploring.</p></div>}<p className="small-note">Levels celebrate time invested. Topic milestones record what you learn.</p></section><section className="panel"><div className="section-title compact"><h2>Next small step</h2><button className="text-button" onClick={openGoal}><Plus size={15}/> Add goal</button></div>{activeGoals.find(g=>g.subject===selected)?<><h3>{activeGoals.find(g=>g.subject===selected)!.title}</h3><p className="muted">{activeGoals.find(g=>g.subject===selected)!.steps.find(s=>!s.done)?.text||'Begin a focus session toward this goal.'}</p><button className="secondary-button small" onClick={()=>setTab('goals')}>Open goals</button></>:<><h3>Start with something small.</h3><p className="muted">Choose one topic you want to understand in {subject.name}.</p><div className="topic-chips">{subject.topics.slice(0,3).map(topic=><button key={topic} onClick={()=>{setGoalSubject(selected);setGoalTitle(topic);setGoalOpen(true)}}>{topic}</button>)}</div></>}</section></div>
